function VsBonusGamePlayerChoice(index){this.Index=index;this.PickType=0}
GameConnection.prototype.SendBonusRequest=function(param){if(this.requestState==RequestState.Block){console.error("Connectiontotheserverwasinterruptedandcan'tsendmorerequests!");console.error("Requestattemptwas-Bonus")}if(this.srvResponse.NextGameActions!=null&&this.srvResponse.NextGameActions.indexOf(NextGameAction.Bonus)<0){console.warn("SendBonusRequestskipped");return}vardata=newRequestData;data.Fields={};data.Url=ServerOptions.serverUrl+ServerOptions.gameServiceUri;data.Fields[GameProtocolDictionary.Actions.action]=GameProtocolDictionary.Actions.doBonus;data.Fields[GameProtocolDictionary.symbol]=this.symbol;if(param!=null)if(param.PickType==0)data.Fields[GameProtocolDictionary.BonusGame.bonusGameChoice]=Number(param.Index).toString();else{data.Fields[GameProtocolDictionary.BonusGame.lInd]=Number(param.Index).toString();data.Fields[GameProtocolDictionary.BonusGame.bonusGameChoice]=Number(param.PickType).toString()}elsethis.WaitInTransition(true);if(this.requestState!=RequestState.Idle){if(this.requestState==RequestState.PickBonus){console.error("Triedtopickinbonuswithoutwaitingforresult!");return}if(param!=null)this.queuedState=RequestState.PickBonus;elsethis.queuedState=RequestState.InitBonus;this.queuedRequest=data}else{if(param!=null)this.requestState=RequestState.PickBonus;elsethis.requestState=RequestState.InitBonus;this.SendRequest(data)}};
BonusPickConnection.prototype.SendItemPick=function(itemId){if(this.lastResponse.GameOver)console.error("You can't pick when the game is over!");else{var option=new VsBonusGamePlayerChoice(itemId);EventManager.Trigger(GameEvents.evtBonusPickRequest+this.xtLayer.gameSymbol,option)}};
BonusPickConnection.prototype.ItemsStatus=function(){if(this.lastResponse.BonusTable.Status!=null)return this.lastResponse.BonusTable.Status;return null};
BonusGameMultiplePicks.prototype.ActivatePicks=function(type,data){if(type==CAT_Event.CallbackType.EndOfEvent)this.indicatorShow.cat.UnregisterCallback(this.indicatorShow.id,this.ActivatePicks,this);var bonusData=XT.GetObject(Vars.BonusData);XT.SetInt(Vars.BonusTotalWinDisplayed,bonusData.WinPoints);for(var itemIndex=0;itemIndex<this.pickItems.length;itemIndex++){if(itemIndex>=bonusData.ItemsStatus.length)continue;this.pickItems[itemIndex].ActivateInput(bonusData.ItemsStatus[itemIndex]<=0)}};
VideoSlotsConnectionXTLayer.prototype.OnBonusPick=function(){var i=XT.GetInt(Vars.BonusPickItemIndex);this.bonusConnection.SendItemPick(i);XT.SetBool(Vars.CanAnimateValues,true)};
